(function(){const msgBtn=document.getElementById("msgActionBtn");if(!msgBtn)return;let notifActive=false;msgBtn.addEventListener("click",function(e){e.preventDefault();e.stopPropagation();if(notifActive){if(wallTV&&wallTV.dismissCCTVMessage)wallTV.dismissCCTVMessage();notifActive=false}else{if(wallTV&&wallTV.triggerCCTVMessage){wallTV.triggerCCTVMessage();notifActive=true;const ping=msgBtn.querySelector(".msg-ping");if(ping)ping.style.display="none";setTimeout(()=>{notifActive=false},5500)}}})})();